//! Method calls on the date objects with PHP values (argument parsing, setters/getters, static methods
//! through instances, (un)serialisation, comparisons, clone, the uninitialised state) against PHP 8.5.13
//! (`tests/vectors/methods.json`, generated by `methods.gen.php`; regenerate with
//! `crates/twig-date/tests/vectors/regen.sh methods`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, IntervalObject, TimeZoneObject, classes};
use twig_value::object::{CallArgs, StdClass};
use twig_value::{Array, ObjectRef, PhpString, Value, compare, convert, dump};

fn date(c: &Ctx, cls: twig_value::object::ClassRef, s: &str) -> ObjectRef {
    DateObject::construct(&c.ctx, cls, s.as_bytes(), None).unwrap()
}

fn make(c: &Ctx, t: &Json) -> Value {
    let (kind, arg) = (s(&t[0]), s(&t[1]));
    Value::Object(match kind {
        "dt" => date(c, classes::datetime(), arg),
        "dti" => date(c, classes::datetime_immutable(), arg),
        "tz" => TimeZoneObject::construct(&c.ctx, arg.as_bytes()).unwrap(),
        "iv" => IntervalObject::construct(&c.ctx, arg.as_bytes()).unwrap(),
        "ivs" => IntervalObject::create_from_date_string(&c.ctx, arg.as_bytes()).unwrap(),
        "std" => StdClass::new().into_ref(),
        "int" => return Value::Int(arg.parse().unwrap()),
        other => panic!("kind {other}"),
    })
}

/// The generator's `arg_value()`.
fn arg_value(c: &Ctx, v: &Json) -> Value {
    if let Json::Object(m) = v
        && m.len() == 1
        && let Some((k, a)) = m.iter().next()
        && k.starts_with('$')
    {
        let a_str = a.as_str().unwrap_or("");
        return match k.as_str() {
            "$tz" => Value::Object(TimeZoneObject::construct(&c.ctx, a_str.as_bytes()).unwrap()),
            "$dt" => Value::Object(date(c, classes::datetime(), a_str)),
            "$dti" => Value::Object(date(c, classes::datetime_immutable(), a_str)),
            "$iv" => Value::Object(IntervalObject::construct(&c.ctx, a_str.as_bytes()).unwrap()),
            "$std" => Value::Object(StdClass::new().into_ref()),
            "$float" => Value::Float(match a_str {
                "NAN" => f64::NAN,
                "INF" => f64::INFINITY,
                _ => f64::NEG_INFINITY,
            }),
            other => panic!("arg {other}"),
        };
    }
    match v {
        Json::Null => Value::Null,
        Json::Bool(b) => Value::Bool(*b),
        Json::Number(n) => match n.as_i64() {
            Some(i) => Value::Int(i),
            None => Value::Float(n.as_f64().unwrap()),
        },
        Json::String(s) => Value::String(PhpString::from(bytes(&Json::String(s.clone())))),
        Json::Array(items) => {
            Value::Array(Array::from_values(items.iter().map(|x| arg_value(c, x))))
        }
        Json::Object(m) => {
            let mut a = Array::new();
            for (k, x) in m {
                a.insert(k.as_str(), arg_value(c, x));
            }
            Value::Array(a)
        }
    }
}

/// The generator's `encode()`.
fn encode(v: &Value) -> Json {
    match v {
        Value::Object(o) if o.instance_of("DateTimeInterface") => {
            let show = match call(
                o,
                "format",
                vec![php_str("Y-m-d H:i:s.u T P U e")],
                &mut Vec::new(),
            ) {
                Ok(s) => Json::String(str_val(&s)),
                Err(e) => Json::String(exc(&e)),
            };
            serde_json::json!({"$class": o.class_name(), "show": show})
        }
        Value::Object(o) if o.instance_of("DateTimeZone") => {
            let name = str_val(&call(o, "getName", vec![], &mut Vec::new()).unwrap());
            let a = convert::to_array(v, &mut Vec::new()).unwrap();
            serde_json::json!({"$class": "DateTimeZone", "name": name, "type": to_json(a.get_str(b"timezone_type").unwrap())})
        }
        Value::Object(o) if o.instance_of("DateInterval") => {
            let fmt = str_val(
                &call(
                    o,
                    "format",
                    vec![php_str("%y %m %d %h %i %s %f %R %a")],
                    &mut Vec::new(),
                )
                .unwrap(),
            );
            let a = convert::to_array(v, &mut Vec::new()).unwrap();
            serde_json::json!({"$class": "DateInterval", "fmt": fmt, "props": to_json(&Value::Array(a))})
        }
        Value::Object(o) => serde_json::json!({"$class": o.class_name()}),
        Value::Array(a) => {
            // array_map() keeps the keys; encode each value.
            if a.is_list() {
                Json::Array(a.values().map(encode).collect())
            } else {
                let mut m = serde_json::Map::new();
                for (k, x) in a.iter() {
                    m.insert(enc(k.to_php_string().as_bytes()), encode(x));
                }
                Json::Object(m)
            }
        }
        Value::Float(f) if !f.is_finite() => {
            let s = if f.is_nan() {
                "NAN"
            } else if *f > 0.0 {
                "INF"
            } else {
                "-INF"
            };
            serde_json::json!({"$float": s})
        }
        other => to_json(other),
    }
}

#[test]
fn calls() {
    let v = load("methods");
    let c = Ctx::new();
    c.now(1_700_000_000, 123_456);
    assert!(
        c.ctx
            .default_timezone_set(b"Europe/Vilnius", &mut Vec::new())
            .unwrap()
    );
    let mut r = Report::new("method calls");
    for case in v["calls"].as_array().unwrap() {
        let target = make(&c, &case[0]);
        let o = obj(target.clone());
        let method = s(&case[1]);
        let mut args = CallArgs::new();
        for a in case[2].as_array().unwrap() {
            let val = arg_value(&c, &a[1]);
            match a[0].as_str() {
                None => args = args.arg(val),
                Some(name) => args = args.named_arg(name, val),
            }
        }
        let mut diags = Vec::new();
        let (res, same) = match o.call_method(method, args, &mut diags) {
            Ok(ret) => {
                let same = matches!(&ret, Value::Object(x) if ObjectRef::ptr_eq(x, &o));
                (encode(&ret), same)
            }
            Err(e) => (Json::String(exc(&e)), false),
        };
        let what = || format!("{} {} {}", case[0], method, case[2]);
        r.eq(res, case[3].clone(), what);
        r.eq(Json::Bool(same), case[4].clone(), || {
            format!("same: {}", what())
        });
        r.eq(encode(&target), case[5].clone(), || {
            format!("after: {}", what())
        });
        r.eq(Json::from(diag_strings(&diags)), case[6].clone(), || {
            format!("diagnostics: {}", what())
        });
    }
    r.finish();
}

#[test]
fn comparisons() {
    let v = load("methods");
    let c = Ctx::new();
    c.now(1_700_000_000, 123_456);
    assert!(
        c.ctx
            .default_timezone_set(b"Europe/Vilnius", &mut Vec::new())
            .unwrap()
    );
    let mut r = Report::new("comparisons");
    for case in v["compare"].as_array().unwrap() {
        let a = make(&c, &case[0]);
        let b = make(&c, &case[1]);
        let mut diags = Vec::new();
        let res = |x: Result<Json, twig_value::PhpError>| match x {
            Ok(j) => j,
            Err(e) => Json::String(exc(&e)),
        };
        let eq = res(compare::equals(&a, &b, &mut diags).map(Json::Bool));
        let lt = res(compare::less(&a, &b, &mut diags).map(Json::Bool));
        let gt = res(compare::greater(&a, &b, &mut diags).map(Json::Bool));
        let sp = res(compare::spaceship(&a, &b, &mut diags).map(Json::from));
        let what = || format!("{} {}", case[0], case[1]);
        r.eq(eq, case[2].clone(), || format!("== {}", what()));
        r.eq(lt, case[3].clone(), || format!("< {}", what()));
        r.eq(gt, case[4].clone(), || format!("> {}", what()));
        r.eq(sp, case[5].clone(), || format!("<=> {}", what()));
        r.eq(Json::from(diag_strings(&diags)), case[6].clone(), || {
            format!("diagnostics {}", what())
        });
    }
    r.finish();
}

#[test]
fn sequences() {
    let v = load("methods");
    let c = Ctx::new();
    c.now(1_700_000_000, 123_456);
    assert!(
        c.ctx
            .default_timezone_set(b"Europe/Vilnius", &mut Vec::new())
            .unwrap()
    );
    let mut r = Report::new("sequences");
    for seq in v["sequences"].as_array().unwrap() {
        let name = s(&seq[0]);
        let mut steps: Vec<Json> = Vec::new();
        let step = |n: &str, j: Json| serde_json::json!([n, j]);
        let res = |x: Result<Value, twig_value::PhpError>| match x {
            Ok(v) => encode(&v),
            Err(e) => Json::String(exc(&e)),
        };
        match name {
            "uninitialized" => {
                let d = date(&c, classes::datetime(), "2024-01-01");
                let mut diags = Vec::new();
                if let Err(e) = call(&d, "__construct", vec![php_str("garbage")], &mut diags) {
                    steps.push(step("construct", Json::String(exc(&e))));
                }
                for (m, a) in [
                    ("format", vec![php_str("Y")]),
                    ("getTimestamp", vec![]),
                    ("modify", vec![php_str("+1 day")]),
                    ("getTimezone", vec![]),
                    ("setTime", vec![Value::Int(1), Value::Int(2)]),
                ] {
                    steps.push(step(m, res(call(&d, m, a, &mut diags))));
                }
                steps.push(step(
                    "clone",
                    res(d.clone_object(&mut diags).map(Value::Object)),
                ));
                let now = Value::Object(date(&c, classes::datetime(), "now"));
                steps.push(step(
                    "compare",
                    match compare::equals(&Value::Object(d.clone()), &now, &mut diags) {
                        Ok(b) => Json::Bool(b),
                        Err(e) => Json::String(exc(&e)),
                    },
                ));
                let vd = dump::var_dump(&Value::Object(d.clone()), &mut diags).unwrap();
                let vd = enc(vd.as_bytes());
                let hash = vd.find('#').unwrap();
                let end = vd[hash..].find(' ').unwrap() + hash;
                steps.push(step(
                    "var_dump",
                    Json::String(format!("{}#N{}", &vd[..hash], &vd[end..])),
                ));
            }
            "clone" => {
                let d = date(&c, classes::datetime(), "2024-01-01 10:00");
                let cl = d.clone_object(&mut Vec::new()).unwrap();
                call(&cl, "modify", vec![php_str("+1 day")], &mut Vec::new()).unwrap();
                steps.push(step("orig", encode(&Value::Object(d))));
                steps.push(step("clone", encode(&Value::Object(cl))));
            }
            "immutable" => {
                let i = date(&c, classes::datetime_immutable(), "2024-01-01 10:00");
                let mut diags = Vec::new();
                i.write_property(b"foo", php_str("bar"), &mut diags)
                    .unwrap();
                let iv = IntervalObject::construct(&c.ctx, b"P1D").unwrap();
                let j = obj(call(&i, "add", vec![Value::Object(iv)], &mut diags).unwrap());
                steps.push(step("orig", encode(&Value::Object(i))));
                steps.push(step("new", encode(&Value::Object(j.clone()))));
                let foo = j
                    .read_property(b"foo", twig_value::object::FetchMode::Read, &mut diags)
                    .unwrap();
                steps.push(step("foo", to_json(&foo)));
                steps.push(step("diags", Json::from(diag_strings(&diags))));
            }
            other => panic!("sequence {other}"),
        }
        r.eq(Json::Array(steps), seq[1].clone(), || {
            format!("sequence {name}")
        });
    }
    r.finish();
}
